SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷八十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ce294d52ced25002a7ab63dd3c7dc2190f538b72/content/books/zizhi-tongjian/vol-286/year-0947/part-05/sources/library/jiuwudaishi-089-liu-xu-office/source.txt", "note": "《旧五代史》卷八十九，段落 jiu-wudaishi-205deb4a7860-p002141；EPUB电子本，纸本及异文待核", "id": "bd6b7cb2-ad69-571e-93f5-ada3a65b9c3e"}, {"title": "旧五代史·卷九十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ce294d52ced25002a7ab63dd3c7dc2190f538b72/content/books/zizhi-tongjian/vol-286/year-0947/part-05/sources/library/jiuwudaishi-099-947-envoy/source.txt", "note": "《旧五代史》卷九十九，段落 jiu-wudaishi-205deb4a7860-p002426；EPUB电子本，纸本及异文待核", "id": "4357ab10-0f92-5dbc-b6cd-5eb1dfd30055"}, {"title": "宋史·巻二百五十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ce294d52ced25002a7ab63dd3c7dc2190f538b72/content/books/zizhi-tongjian/vol-286/year-0947/part-05/sources/library/songshi-254-zhang-congen/source.txt", "note": "《宋史》巻二百五十四，段落 songshi-9c6e46fee832-p057468；EPUB电子本，纸本及异文待核", "id": "9780c54d-9b9f-5fbd-b413-40e62d10c8f5"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ce294d52ced25002a7ab63dd3c7dc2190f538b72/content/books/zizhi-tongjian/vol-286/year-0947/part-05/sources/library/tongjian-286-947-zhang-nantang/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003397；电子底本待考，分段待核", "id": "68446a34-3411-5633-ae2b-449fc78954e0"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3c44c1173db8c2bfe524e8a0bfd