INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "刘昫", "aliases": ["劉昫", "刘煦", "劉煦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘昫，端明殿学士、受相职者。", "biography": null, "status": "draft", "id": "b63eeed9-ecc3-575d-aba8-41b03e6caa3e"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "刘九（947年契丹将）", "aliases": ["劉九（947年契丹將）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将。947年刘知远的表章称他率一军从土门向西进入南川，引起太原城中忧惧。原书仅给名刘九，使用职务年代限定，不补真实姓名与生卒年。", "biography": null, "status": "draft", "id": "6704c748-0ad8-5dfe-ac58-80fe4ab22ae1"}, {"name": "白文珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋代州刺史。944年九月在七里烽击败契丹；新史记丙子，旧史壬辰记录太原奏报。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "4144a98b-cc52-5b8e-afec-6ad9ed55b845"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "张从恩", "aliases": ["張從恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，曾任澶州防御使。939年正月任后晋枢密副使。生卒年未载。", "biography": null, "status": "draft", "id": "e1e909ad-c88c-54a5-941c-6116c704a870"}, {"name": "高防", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "昭义节度判官。947年张从恩拟往契丹朝见时，他以晋室亲属应守臣节为由劝谏，未被听从；张离镇后留下他协助赵行迁、王守恩。生卒年未载。", "biography": null, "status": "draft", "id": "603ffd47-a5a9-5c5a-90e1-fdc9ea0bc620"}, {"name": "赵行迁", "aliases": ["趙行遷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "昭义节度副使。947年张从恩赴契丹朝见前，让他主持留后事务，并由王守恩、高防协助。生卒年未载。", "biography": null, "status": "draft", "id": "dd85b151-1c01-5e90-9855-53b893b0053a"}, {"name": "王守恩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王建立的儿子，与张从恩是姻亲。947年在上党，以左骁卫大将军身份被张从恩暂派为巡检使，协助赵行迁。姻亲具体双方未明，不补具体婚配，生卒年未载。", "biography": null, "status": "draft", "id": "72fe9a16-4716-54d0-bc82-5e7feadc013e"}, {"name": "王建立", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：王建立。", "biography": null, "status": "draft", "id": "2addb586-2a21-57fe-a7f1-0f93cd12ebdd"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "耶律德光以赏赐三十万名将士为由，命刘昫筹措钱帛", "start_year": 947, "end_year": 947, "time_original": "947年初，具体月日未载", "dynasty": "五代十国", "description": "耶律德光以赏赐三十万名将士为由，命刘昫筹措钱帛。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a6ca8df5-f979-53f1-868b-6e23ca27908f"}, {"title": "府库已空，刘昫请求向都城居民强制征借钱帛，将相也不能免除", "start_year": 947, "end_year": 947, "time_original": "947年初，具体月日未载", "dynasty": "五代十国", "description": "府库已空，刘昫请求向都城居民强制征借钱帛，将相也不能免除。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8a698518-6c10-5203-8a07-5b87aaeaef26"}, {"title": "契丹分派数十名使者到各州征借钱帛，以重刑逼迫民众", "start_year": 947, "end_year": 947, "time_original": "947年初，具体月日未载", "dynasty": "五代十国", "description": "契丹分派数十名使者到各州征借钱帛，以重刑逼迫民众。", "phases": [], "location_name": "各州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "683e706e-862b-5ee0-b636-9fe87b7ee06d"}, {"title": "史书记征得钱帛没有赏军，而是存入内库，准备运回契丹", "start_year": 947, "end_year": 947, "time_original": "947年初，具体月日未载", "dynasty": "五代十国", "description": "史书记征得钱帛没有赏军，而是存入内库，准备运回契丹。", "phases": [], "location_name": "大梁内库至契丹（计划去向）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c3509969-6741-59da-93da-c98ecd725d45"}, {"title": "史书记强制征敛使内外怨愤，人们开始希望驱逐契丹", "start_year"